namespace HybridCPU_ISE.Tests.Architecture;
public sealed class Rf129asReplayTokenInvalidInputInventoryTests
{[Fact] public void UnboundAndBoundaryReplayMemoryFailsClosed(){string r=Read("HybridCPU_ISE","CloseToHSL","Core","Pipeline","MicroOps","Replay","ReplayToken.cs");Assert.Contains("token remains unbound",r,StringComparison.Ordinal);Assert.Contains("GetRequiredMainMemory",r,StringComparison.Ordinal);Assert.Contains("MainMemoryBindingUnavailableException",r,StringComparison.Ordinal);Assert.Contains("Replay/rollback must fail closed",r,StringComparison.Ordinal);Assert.Contains("JsonSerializer.Deserialize<ReplayToken>(json)",r,StringComparison.Ordinal);}private static string Read(params string[] p)=>File.ReadAllText(Path.Combine(new[]{Root()}.Concat(p).ToArray()));private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"HybridCPU_ISE")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
